const PAYLOAD = {"modified": [{"path": "app/lib/templates.server.ts", "fromShas": ["8a164ce3e99c4fdfbd826bf5bedb57c3d33226ad817d3ecdd22a85ed9c9a9f7c", "f66e54c174ec1ba54bec51699c5f1c9a02a6b7310ad55394c795d536b51072da"], "toSha": "38dae7b342bb1de00ce79caa4cdd9f42c744890306b0dc78341b7738e8372d3d", "content": "/**\n * Every event's template, along with its variables.\n *\n * Everything in one place: which template to call, what to fill into its\n * {{1}} {{2}}, and what goes into the button. If some text changes later,\n * only this file has to change.\n *\n * The order of params is the order the body is written in WhatsApp Manager.\n * One position out of place and the customer gets a garbled message.\n */\n\nexport type Vars = {\n  name: string;      // Rahul\n  order: string;     // Z1001\n  item: string;      // Portable Blender + 1 more item\n  amount: string;    // INR 899\n  eta: string;       // 3-7 September\n  courier: string;   // Delhivery\n  tracking: string;  // 1234567890\n  city: string;      // Patna\n  address: string;   // Bettiah, Bihar 845438\n  reason: string;    // Customer not reachable\n  attempts: string;  // three\n  date: string;      // 27 August, 3:45 PM\n  method: string;    // UPI\n  code: string;      // WELCOME10\n  handle: string;    // portable-blender\n  cart: string;      // a7f3k9\n};\n\ntype Def = {\n  template: string;\n  params: (v: Vars) => string[];\n  /** the trailing part of the dynamic URL button */\n  button?: (v: Vars) => string;\n  marketing?: boolean;\n};\n\nexport const EVENTS: Record<string, Def> = {\n  order_created:    { template: \"order_placed\",      params: v => [v.name, v.order, v.item, v.amount, v.eta] },\n  cod_confirm:      { template: \"cod_confirm\",       params: v => [v.name, v.order, v.item, v.amount] },\n  cod_reminder:     { template: \"cod_reminder\",      params: v => [v.name, v.order, v.item, v.amount] },\n  cod_confirmed:    { template: \"cod_confirmed\",     params: v => [v.name, v.order, v.item, v.eta] },\n  order_paid:       { template: \"payment_received\",  params: v => [v.name, v.amount, v.order, v.item, v.eta] },\n\n  shipped:          { template: \"order_shipped\",     params: v => [v.name, v.order, v.item, v.courier, v.tracking, v.eta], button: v => v.tracking },\n  in_transit:       { template: \"order_in_transit\",  params: v => [v.name, v.order, v.city, v.item, v.eta],               button: v => v.tracking },\n  out_for_delivery: { template: \"out_for_delivery\",  params: v => [v.name, v.order, v.item, v.address, v.amount],         button: v => v.tracking },\n  delivery_failed:  { template: \"delivery_failed\",   params: v => [v.name, v.order, v.item, v.reason] },\n  rto_alert:        { template: \"rto_alert\",         params: v => [v.name, v.order, v.attempts, v.item] },\n  delivered:        { template: \"order_delivered\",   params: v => [v.name, v.order, v.item, v.date] },\n\n  cancelled:        { template: \"order_cancelled\",   params: v => [v.name, v.order, v.item, v.amount] },\n  refunded:         { template: \"refund_initiated\",  params: v => [v.name, v.amount, v.order, v.item, v.method] },\n\n  abandoned_1:      { template: \"abandoned_cart_1\",  params: v => [v.name, v.item, v.amount], button: v => v.cart, marketing: true },\n  abandoned_2:      { template: \"abandoned_cart_2\",  params: v => [v.name, v.item, v.code],   button: v => v.cart, marketing: true },\n  review:           { template: \"review_request\",    params: v => [v.name, v.item],           button: v => v.handle, marketing: true },\n  back_in_stock:    { template: \"back_in_stock\",     params: v => [v.name, v.item, v.amount], button: v => v.handle, marketing: true },\n};\n\n/** Empty Vars, so that every field is present everywhere. */\nexport function blankVars(): Vars {\n  return {\n    name: \"\", order: \"\", item: \"\", amount: \"\", eta: \"\", courier: \"\",\n    tracking: \"\", city: \"\", address: \"\", reason: \"\", attempts: \"\",\n    date: \"\", method: \"\", code: \"\", handle: \"\", cart: \"\",\n  };\n}\n\n/**\n * Lines that a Cash-on-Delivery app adds to the order but that the customer\n * never thinks of as a product. COD King writes a zero-priced \"Partial\n * Payment\" line, and some apps duplicate the real product at zero. Naming\n * those in a message reads like a mistake, so they are left out.\n */\nconst HELPER_LINE = /partial\\s*payment|cod\\s*(fee|charge|advance)|shipping\\s*protection|insurance/i;\n\n/**\n * The order's item names on a single line.\n *   one item       -> \"Portable Blender\"\n *   more than one  -> \"Portable Blender + 2 more items\"\n * Long names get truncated, otherwise they break badly on WhatsApp.\n */\nexport function itemLine(order: any): string {\n  let li: any[] = order?.line_items ?? [];\n  if (!li.length) return \"your order\";\n\n  const real = li.filter((l: any) => {\n    const title = String(l?.title ?? l?.name ?? \"\");\n    if (HELPER_LINE.test(title)) return false;\n    // A zero-priced line beside a paid one is the COD app's placeholder,\n    // not a free gift the customer chose.\n    const price = Number(l?.price ?? l?.original_price ?? 0);\n    if (li.length > 1 && Number.isFinite(price) && price === 0) return false;\n    return true;\n  });\n\n  if (real.length) li = real;\n\n  let first = String(li[0].title ?? li[0].name ?? \"your order\").trim();\n  if (first.length > 46) first = first.slice(0, 45).trimEnd() + \"…\";\n\n  const rest = li.length - 1;\n  if (rest <= 0) return first;\n  return `${first} + ${rest} more item${rest > 1 ? \"s\" : \"\"}`;\n}\n\n/**\n * What the order is really worth.\n *\n * A partial-payment COD app can leave total_price at zero on the webhook\n * that creates the order - the money is recorded as still outstanding\n * instead. \"Total: INR 0\" in a message looks broken, so we take the first\n * figure that is actually a number greater than zero.\n */\nexport function orderTotal(order: any): string | null {\n  const candidates = [\n    order?.total_price,\n    order?.current_total_price,\n    order?.total_outstanding,\n    order?.subtotal_price,\n  ];\n  for (const c of candidates) {\n    const n = Number(c);\n    if (Number.isFinite(n) && n > 0) return String(c);\n  }\n  return candidates.find((c) => c != null && String(c).trim() !== \"\") ?? null;\n}\n\n/** What is still to be collected at the door, if anything. */\nexport function amountDue(order: any): string | null {\n  const n = Number(order?.total_outstanding);\n  if (Number.isFinite(n) && n > 0) return String(order.total_outstanding);\n  return null;\n}\n\n/** \"INR 899\" - so it always looks the same in every message. */\nexport function money(amount?: string | null, currency?: string | null): string {\n  if (!amount) return \"\";\n  const n = Number(amount);\n  const clean = Number.isFinite(n) ? n.toLocaleString(\"en-IN\") : amount;\n  return `${currency || \"INR\"} ${clean}`;\n}\n\n/**\n * The delivery estimate - something like \"3-7 September\".\n *\n * This is an estimate, not a promise. Per the shipping policy it is 2 to 6\n * working days after dispatch. We skip Sundays, because couriers skip them too.\n */\nexport function etaRange(from = new Date(), minDays = 2, maxDays = 6): string {\n  const add = (d: Date, work: number) => {\n    const out = new Date(d);\n    let left = work;\n    while (left > 0) {\n      out.setDate(out.getDate() + 1);\n      if (out.getDay() !== 0) left--;   // Sundays do not count\n    }\n    return out;\n  };\n  const a = add(from, minDays);\n  const b = add(from, maxDays);\n  const M = [\"January\",\"February\",\"March\",\"April\",\"May\",\"June\",\"July\",\"August\",\"September\",\"October\",\"November\",\"December\"];\n\n  if (a.getMonth() === b.getMonth()) return `${a.getDate()}-${b.getDate()} ${M[a.getMonth()]}`;\n  return `${a.getDate()} ${M[a.getMonth()]} - ${b.getDate()} ${M[b.getMonth()]}`;\n}\n\n/** \"27 August, 3:45 PM\" - for the delivered message. */\nexport function stamp(d = new Date()): string {\n  const M = [\"January\",\"February\",\"March\",\"April\",\"May\",\"June\",\"July\",\"August\",\"September\",\"October\",\"November\",\"December\"];\n  let h = d.getHours();\n  const ap = h >= 12 ? \"PM\" : \"AM\";\n  h = h % 12 || 12;\n  const m = String(d.getMinutes()).padStart(2, \"0\");\n  return `${d.getDate()} ${M[d.getMonth()]}, ${h}:${m} ${ap}`;\n}\n\n/** A short one-line shipping address - \"Bettiah, Bihar 845438\". */\nexport function shortAddress(order: any): string {\n  const a = order?.shipping_address ?? order?.billing_address ?? {};\n  return [a.city, a.province, a.zip].filter(Boolean).join(\", \") || \"your address\";\n}\n\n/** A human-readable line for display on the admin page. */\nexport function preview(event: string, v: Vars): string {\n  const def = EVENTS[event];\n  if (!def) return \"\";\n  return `${def.template}(${def.params(v).filter(Boolean).join(\", \")})`;\n}\n"}, {"path": "app/lib/webhook.server.ts", "fromShas": ["48dbebdfba962aaa33aaddb10b498438eacdab49cceaeeb47cd5a6ef2802822c", "6606a8a7fdf1faa4bb74a1735ed600bf17e3afb0e36302b8a75f9b7da520aa80"], "toSha": "c10501ec26bae66309c1d4d137c03b3f611f27618856588be1261cf615dd4f41", "content": "import db from \"../db.server\";\nimport { itemLine, shortAddress, orderTotal, amountDue } from \"./templates.server\";\n\n/**\n * Shopify retries every webhook, and the same event can arrive two or three\n * times. Every delivery carries a unique id in a header. Writing that into a\n * table is the cheapest idempotency there is.\n *\n * True the first time it arrives, false on every repeat.\n *\n * IMPORTANT: call this AFTER authenticate.webhook(). The body is read there,\n * but the headers are still available afterwards.\n */\nexport async function firstDelivery(\n  request: Request,\n  topic: string,\n  shop: string,\n): Promise<boolean> {\n  const id = request.headers.get(\"x-shopify-webhook-id\");\n  if (!id) return true; // cannot dedupe, let it through\n\n  try {\n    await db.webhookEvent.create({ data: { id, topic, shop } });\n    return true;\n  } catch {\n    // unique constraint -> this delivery has already been handled\n    return false;\n  }\n}\n\n/** Fetch the shop's row, create it if there is none. */\nexport async function ensureShop(domain: string) {\n  return db.shop.upsert({\n    where: { domain },\n    update: {},\n    create: { domain },\n  });\n}\n\n/**\n * Converts Indian numbers to E.164, which the WhatsApp Cloud API demands.\n *\n *   \"9876543210\"        -> \"919876543210\"\n *   \"+91 98765 43210\"   -> \"919876543210\"\n *   \"098765-43210\"      -> \"919876543210\"\n *\n * If the number looks unusable, null - so no message goes to a wrong one.\n */\nexport function toE164(raw?: string | null, cc = \"91\"): string | null {\n  if (!raw) return null;\n\n  let d = String(raw).replace(/\\D/g, \"\");\n  if (!d) return null;\n\n  // international format with a \"00\" prefix\n  if (d.startsWith(\"00\")) d = d.slice(2);\n\n  // 10 digit local number -> add the country code\n  if (d.length === 10) return cc + d;\n\n  // 11 digits starting with 0 -> strip the STD 0\n  if (d.length === 11 && d.startsWith(\"0\")) return cc + d.slice(1);\n\n  // already carries a country code\n  if (d.length >= 11 && d.length <= 15) return d;\n\n  return null;\n}\n\n/**\n * Find the order's phone number.\n *\n * The order here is deliberate: SHIPPING ADDRESS first.\n *\n * The customer profile may hold an old number, or one from another country -\n * say a customer who lives abroad but is sending the parcel to India.\n * The delivery message has to reach the person who will receive the parcel,\n * so we look at the shipping address number first.\n */\nexport function pickPhone(order: any): string | null {\n  return toE164(\n    order?.shipping_address?.phone ||\n      order?.phone ||\n      order?.customer?.phone ||\n      order?.billing_address?.phone ||\n      null,\n  );\n}\n\n/** The customer's first name - for \"Hi Rahul\" in the message. */\nexport function pickName(order: any): string {\n  const n =\n    order?.shipping_address?.first_name ||\n    order?.customer?.first_name ||\n    order?.billing_address?.first_name ||\n    \"\";\n  return String(n).trim();\n}\n\n/**\n * Whether this is COD.\n *\n * This check matters most. A COD order fires orders/paid too - but WEEKS\n * LATER, when the courier deposits the cash. Without this guard the\n * customer gets \"Payment received\" 3 weeks on and it reads as spam.\n *\n * NOTE: we do not treat the \"manual\" gateway as COD. Shopify writes that\n * name down even when the shopkeeper marks an order \"Mark as paid\" himself -\n * and that is not COD. We only catch names that plainly say COD.\n */\nexport function isCodOrder(order: any): boolean {\n  const names: string[] = order?.payment_gateway_names || [];\n  if (\n    names.some((g) =>\n      /cash[\\s_-]?on[\\s_-]?delivery|(^|[^a-z])cod([^a-z]|$)/i.test(String(g)),\n    )\n  ) {\n    return true;\n  }\n\n  // Partial-payment COD apps tag the order themselves - COD King writes\n  // \"COD-Verified\". That tag is a plain statement that cash is due.\n  if (/(^|[^a-z])cod([^a-z]|$)/i.test(String(order?.tags ?? \"\"))) return true;\n\n  // And the case that caught us out: those apps create the order with NO\n  // gateway at all and simply leave the balance unpaid, which Shopify shows\n  // as \"pending\" or \"partially paid\". No gateway name to match, but money\n  // still has to be collected at the door - and that is what COD means for\n  // every message this app sends.\n  //\n  // A prepaid order waiting on its gateway looks the same for a few seconds.\n  // We accept that: asking such a customer to confirm is harmless, while\n  // treating a real COD order as prepaid sends \"payment received\" for money\n  // that was never paid.\n  const status = String(order?.financial_status ?? \"\").toLowerCase();\n  const outstanding = Number(order?.total_outstanding ?? 0);\n  if (\n    Number.isFinite(outstanding) &&\n    outstanding > 0 &&\n    (status === \"pending\" || status === \"partially_paid\")\n  ) {\n    return true;\n  }\n\n  return false;\n}\n\n/**\n * Create or update the order row from the payload.\n *\n * This sits in one place because orders/create and orders/paid can arrive\n * in the SAME SECOND. If paid got there first and the order had not been\n * written to the database yet, the answer to \"is this COD?\" came back as\n * \"no idea\" and the guard failed.\n *\n * Both handlers now call this same function, so whichever gets there\n * first - the row gets created and isCod gets filled in correctly.\n */\nexport async function upsertOrder(shopId: string, order: any) {\n  const cod = isCodOrder(order);\n  const phone = pickPhone(order);\n  const name = pickName(order);\n  const orderNumber = order.name ?? `#${order.order_number ?? \"\"}`;\n\n  const addr = order?.shipping_address ?? order?.billing_address ?? {};\n\n  const common = {\n    orderNumber,\n    customerName: name || null,\n    phone,\n    email: order.email ?? null,\n    totalPrice: orderTotal(order),\n    // What is still to be collected at the door. On a partial-payment COD\n    // order this is smaller than the total, and it is the only figure the\n    // customer should ever be asked for.\n    outstanding: amountDue(order),\n    currency: order.currency ?? null,\n    financial: order.financial_status ?? null,\n    gateway: (order.payment_gateway_names ?? []).join(\", \") || null,\n    isCod: cod,\n\n    // These three get filled in right here because when the courier update\n    // arrives we do not have Shopify's payload at all - only the tracking\n    // number. Then \"Portable Blender + 1 more item\" would come from nowhere.\n    itemLine: itemLine(order),\n    city: addr?.city ?? null,\n    address: shortAddress(order),\n  };\n\n  return db.orderRecord.upsert({\n    where: { shopId_shopifyId: { shopId, shopifyId: String(order.id) } },\n    update: common,\n    create: { shopId, shopifyId: String(order.id), ...common },\n  });\n}\n"}, {"path": "app/lib/tracksync.server.ts", "fromShas": ["83e7f136ec9b893681c06114f96b5d417a8b1da8c77e716fcec7ddd851998cc3", "e76cf6eff299dcc727f1b011a0f39671a972475f9394307e75b93ef8bad769e6"], "toSha": "4dfeb32d4896a736b678a964cd297da388a78af35b2c8ffc2bb2d4ff94a86401", "content": "import db from \"../db.server\";\nimport { normalize, failReason, inWords, type Norm } from \"./track.server\";\nimport { queueMessage, eventEnabled } from \"./notify.server\";\nimport { blankVars, money, stamp, etaRange } from \"./templates.server\";\n\n/**\n * What to do when a courier scan arrives.\n *\n * This is the only place in the whole app where the \"out for delivery\",\n * \"delivered\", \"delivery failed\" and \"RTO\" messages are built. These four\n * never come from Shopify.\n *\n * Two layers keep a message from going out twice:\n *   1. If the status is the same as before we do nothing at all.\n *   2. If the same event still arrives twice, MessageLog's\n *      unique([orderId, event, channel]) stops it.\n */\n\n/** which status sends which message */\nconst EVENT_FOR: Record<string, string> = {\n  in_transit: \"in_transit\",\n  out_for_delivery: \"out_for_delivery\",\n  delivered: \"delivered\",\n  exception: \"delivery_failed\",\n  returned: \"rto_alert\",\n};\n\n/** once it lands here nothing further happens - polling stops */\nexport const FINAL = new Set([\"delivered\", \"returned\"]);\n\nexport async function applyToShipment(shipmentId: string, node: any) {\n  const n = normalize(node);\n\n  const sh = await db.shipment.findUnique({\n    where: { id: shipmentId },\n    include: { order: { include: { shop: true } } },\n  });\n  if (!sh) return { changed: false, reason: \"shipment not found\" };\n\n  const before = sh.status;\n  const rec = sh.order;\n  const shop = rec.shop;\n\n  await db.shipment.update({\n    where: { id: sh.id },\n    data: {\n      status: n.status,\n      lastEventAt: n.time ?? sh.lastEventAt ?? new Date(),\n      lastEventDesc: n.desc || sh.lastEventDesc,\n      lastEventLoc: n.location || sh.lastEventLoc,\n      subStatus: n.sub || null,\n      carrier: n.carrierName || sh.carrier,\n      carrierCode: n.carrierCode ?? sh.carrierCode,\n      scans: n.events.length ? JSON.stringify(n.events) : sh.scans,\n    },\n  });\n\n  // The status is exactly what it was - no question of a message.\n  if (n.status === before) return { changed: false, status: n.status };\n\n  const event = EVENT_FOR[n.status];\n  if (!event) return { changed: true, status: n.status };\n  if (!eventEnabled(shop, event)) return { changed: true, status: n.status, skipped: \"turned off\" };\n\n  const v = blankVars();\n  v.name = rec.customerName || \"there\";\n  v.order = rec.orderNumber;\n  v.item = rec.itemLine || \"your order\";\n  // On a partial-payment COD order the balance is what the delivery agent\n  // collects, not the order total. Asking for the total would be asking for\n  // money the customer has already paid once.\n  v.amount = money(rec.outstanding ?? rec.totalPrice, rec.currency);\n  v.courier = n.carrierName || sh.carrier || \"our courier partner\";\n  v.tracking = sh.trackingNo || \"\";\n  v.city = n.location || rec.city || \"your city\";\n  v.address = rec.address || n.location || \"your address\";\n  v.eta = etaRange();\n  v.date = stamp(n.time ?? new Date());\n  v.reason = failReason(n.sub, n.desc);\n  v.attempts = inWords(Math.max(n.attempts, 1));\n\n  // Only say \"keep the cash ready\" when the order really is COD.\n  if (event === \"out_for_delivery\") {\n    const due = Number(rec.outstanding ?? rec.totalPrice);\n    if (!rec.isCod || (Number.isFinite(due) && due <= 0)) v.amount = \"Already paid\";\n  }\n\n  await queueMessage({\n    shopId: shop.id,\n    orderId: rec.id,\n    event,\n    to: rec.phone,\n    vars: v,\n  });\n\n  console.log(`[track] ${rec.orderNumber} ${before} -> ${n.status} (${event} sent)`);\n  return { changed: true, status: n.status, event };\n}\n\n/**\n * The push carries only the tracking number, not our shipment id (we do\n * send `tag`, but it does not come back on every courier). So looking it up\n * by number is the only dependable way.\n */\nexport async function applyByNumber(shopId: string, number: string, node: any) {\n  if (!number) return { changed: false, reason: \"number is empty\" };\n\n  const rows = await db.shipment.findMany({\n    where: { trackingNo: number, order: { shopId } },\n    orderBy: { createdAt: \"desc\" },\n    take: 3,\n  });\n  if (rows.length === 0) return { changed: false, reason: `${number} is not one of ours` };\n\n  const out = [];\n  for (const r of rows) out.push(await applyToShipment(r.id, node));\n  return out[0];\n}\n\nexport type { Norm };\n"}, {"path": "app/routes/webhooks.orders.create.tsx", "fromShas": ["391bbe0583bb4fb1313f250e4b15b6edbdb96abdff468e1a4c5afa9e0e671f6f", "deaf47a5aa4b0afd11fd5c5d56edbde344ad036eba2c5d2f2d6d71522791f086"], "toSha": "6b9343e7eeea4689fbfa6dc4cbc787725c0d5d3fd509b94a999a38b7f4c2616c", "content": "import type { ActionFunctionArgs } from \"react-router\";\nimport { authenticate } from \"../shopify.server\";\nimport { firstDelivery, ensureShop, upsertOrder } from \"../lib/webhook.server\";\nimport { queueMessage, eventEnabled } from \"../lib/notify.server\";\nimport { blankVars, itemLine, money, etaRange, orderTotal } from \"../lib/templates.server\";\nimport { markConverted } from \"../lib/abandoned.server\";\n\nexport const action = async ({ request }: ActionFunctionArgs) => {\n  const { shop, topic, payload } = await authenticate.webhook(request);\n\n  if (!(await firstDelivery(request, topic, shop))) return new Response();\n\n  const order = payload as any;\n  const s = await ensureShop(shop);\n  const rec = await upsertOrder(s.id, order);\n\n  // This first. Sending \"your cart is waiting\" to someone who has just\n  // bought is the worst possible experience - and it also costs money at\n  // the Marketing rate.\n  await markConverted(s.id, [order.cart_token, order.checkout_token, order.checkout_id]);\n\n  const v = blankVars();\n  v.name = rec.customerName || \"there\";\n  v.order = rec.orderNumber;\n  v.item = itemLine(order);\n  v.amount = money(orderTotal(order), order.currency);\n  v.eta = etaRange();\n\n  // For COD we ask for confirmation, for prepaid we send \"order received\".\n  // Getting COD confirmed cuts RTO (the parcel coming back) the most.\n  const event = rec.isCod && s.codConfirm ? \"cod_confirm\" : \"order_created\";\n\n  if (eventEnabled(s, event)) {\n    await queueMessage({\n      shopId: s.id,\n      orderId: rec.id,\n      event,\n      to: rec.phone,\n      vars: v,\n    });\n  }\n\n  return new Response();\n};\n"}, {"path": "app/routes/webhooks.orders.paid.tsx", "fromShas": ["510e01b9a8aef06e84ad6d2b2e01288a3f10cfa1adf79206181cc4ad99449739", "ef773244c565d3bcca48b7e3b2f42af04e6da416eae9978152bef2feaffadf63"], "toSha": "bdbd471c4eaa7707e7859eb8f36f0088b3e5d287f6585b4304c329946265013f", "content": "import type { ActionFunctionArgs } from \"react-router\";\nimport { authenticate } from \"../shopify.server\";\nimport { firstDelivery, ensureShop, upsertOrder } from \"../lib/webhook.server\";\nimport { queueMessage, eventEnabled } from \"../lib/notify.server\";\nimport { blankVars, itemLine, money, etaRange, orderTotal } from \"../lib/templates.server\";\n\nexport const action = async ({ request }: ActionFunctionArgs) => {\n  const { shop, topic, payload } = await authenticate.webhook(request);\n\n  if (!(await firstDelivery(request, topic, shop))) return new Response();\n\n  const order = payload as any;\n  const s = await ensureShop(shop);\n\n  // upsert, not findUnique: orders/create and orders/paid can arrive in the\n  // same second, and sometimes in the reverse order. Whichever lands first\n  // creates the row and fills in isCod correctly.\n  const rec = await upsertOrder(s.id, order);\n\n  // A COD order fires orders/paid too - but WEEKS LATER, when the courier\n  // deposits the cash. Sending \"Payment received\" then reads as spam; the\n  // parcel was delivered long ago.\n  if (rec.isCod) {\n    console.log(`[orders/paid] ${rec.orderNumber} is COD, no message sent`);\n    return new Response();\n  }\n\n  // Second guard, for the partial-payment case. Shopify fires orders/paid\n  // when the small advance is taken, while the rest is still owed at the\n  // door. Saying \"we have received your payment\" then is simply untrue.\n  const stillOwed = Number(order?.total_outstanding ?? 0);\n  if (Number.isFinite(stillOwed) && stillOwed > 0) {\n    console.log(\n      `[orders/paid] ${rec.orderNumber} still has ${stillOwed} outstanding, no message sent`,\n    );\n    return new Response();\n  }\n\n  if (!eventEnabled(s, \"order_paid\")) return new Response();\n\n  const v = blankVars();\n  v.name = rec.customerName || \"there\";\n  v.order = rec.orderNumber;\n  v.item = itemLine(order);\n  v.amount = money(orderTotal(order), order.currency);\n  v.eta = etaRange();\n\n  await queueMessage({\n    shopId: s.id,\n    orderId: rec.id,\n    event: \"order_paid\",\n    to: rec.phone,\n    vars: v,\n  });\n\n  return new Response();\n};\n"}, {"path": "app/routes/webhooks.orders.cancelled.tsx", "fromShas": ["4ff37b67f9318908489b1a2fa9de59e7d11a61508610e4c51ecac9ddab615c20", "7d2463d856d1dc0fbdbbf9029ee679a05983de02bf1abd43858953a1d1f26e92"], "toSha": "1981cbf300ee87488504724e3721de219d844ab944ce10c8cf831be9a2729de3", "content": "import type { ActionFunctionArgs } from \"react-router\";\nimport { authenticate } from \"../shopify.server\";\nimport db from \"../db.server\";\nimport { firstDelivery, ensureShop, upsertOrder } from \"../lib/webhook.server\";\nimport { queueMessage, eventEnabled } from \"../lib/notify.server\";\nimport { blankVars, itemLine, money, orderTotal } from \"../lib/templates.server\";\n\nexport const action = async ({ request }: ActionFunctionArgs) => {\n  const { shop, topic, payload } = await authenticate.webhook(request);\n\n  if (!(await firstDelivery(request, topic, shop))) return new Response();\n\n  const order = payload as any;\n  const s = await ensureShop(shop);\n  const rec = await upsertOrder(s.id, order);\n\n  await db.orderRecord.update({\n    where: { id: rec.id },\n    data: { cancelledAt: new Date() },\n  });\n\n  if (!eventEnabled(s, \"cancelled\")) return new Response();\n\n  const v = blankVars();\n  v.name = rec.customerName || \"there\";\n  v.order = rec.orderNumber;\n  v.item = itemLine(order);\n  v.amount = money(orderTotal(order), order.currency);\n\n  await queueMessage({\n    shopId: s.id,\n    orderId: rec.id,\n    event: \"cancelled\",\n    to: rec.phone,\n    vars: v,\n  });\n\n  return new Response();\n};\n"}, {"path": "app/routes/proxy.track._index.tsx", "fromShas": ["161bc656ea175c891f45ae9d2a9de86cc4381896bce299c28a8914c19ce5f25b", "364777a90c27d949e7f9d5610fac48d96f286e76f2c202c584b9ebea503422ac", "6f3964d7fa72864bd20614ff115260c52b7e92676027cb6f328d86997d1498ca", "7aab3d0664bf927b1a844a36c82d8ff2e988a8079fa46e2d5d5912c4c11be9a1"], "toSha": "b405e11e198385c2fb45023b4e5a6b8e401a4b93081c246c9ef7768ff445c95f", "content": "import type { LoaderFunctionArgs } from \"react-router\";\nimport db from \"../db.server\";\nimport { authenticate } from \"../shopify.server\";\nimport { shopFromProxy, esc, liquid } from \"../lib/proxy.server\";\nimport { STATUS_LABEL } from \"../lib/track.server\";\nimport { money } from \"../lib/templates.server\";\n\n/**\n * The actual tracking page - zakdor.com/apps/track\n *\n * This is a resource route (no default export), so the Response that\n * leaves here goes straight to the browser. Serving it with Content-Type\n * application/liquid makes Shopify place it between the theme header and\n * footer - the page looks like the rest of the store on its own.\n *\n * It opens in two ways:\n *   /apps/track?n=<tracking number>   - from the WhatsApp button\n *   /apps/track?order=Z1005&pin=8695  - customer types it in\n *\n * The order number alone is not enough. Guessing Z1006 after Z1005 is far\n * too easy, and that would expose someone else's address. So we also ask\n * for the last 4 digits of the phone number, or the email.\n */\n\nconst STEPS = [\"Confirmed\", \"Shipped\", \"In transit\", \"Out for delivery\", \"Delivered\"];\n\n/**\n * How much cash the customer still owes, or null if nothing is due.\n *\n * The COD flag alone is not enough. A partial-payment COD app can create the\n * order with no gateway name at all, and an order written before that was\n * understood is still sitting in the database with isCod false. The balance\n * is the fact that matters: if money is outstanding, it is collected at the\n * door, whatever the flag says.\n */\nfunction cashDue(rec: any): string | null {\n  const out = Number(rec?.outstanding);\n  if (Number.isFinite(out) && out > 0) return String(rec.outstanding);\n  if (!rec?.isCod) return null;\n  const total = Number(rec?.totalPrice);\n  return Number.isFinite(total) && total > 0 ? String(rec.totalPrice) : null;\n}\n\nconst STEP_OF: Record<string, number> = {\n  pending: 1,\n  info_received: 1,\n  in_transit: 2,\n  out_for_delivery: 3,\n  delivered: 4,\n  exception: 2,\n  returned: 2,\n};\n\nfunction fmt(d: any): string {\n  if (!d) return \"\";\n  const x = new Date(d);\n  if (isNaN(x.getTime())) return \"\";\n  return x.toLocaleString(\"en-IN\", {\n    day: \"numeric\", month: \"short\", hour: \"numeric\", minute: \"2-digit\", hour12: true,\n  });\n}\n\nconst CSS = `\n<style>\n.zt-wrap\n{max-width:780px;margin:0 auto;padding:38px 18px 70px;font-family:inherit;color:inherit}\n.zt-h1\n{font-size:30px;line-height:1.15;font-weight:700;margin:0 0 8px;letter-spacing:-.02em;color:inherit}\n.zt-sub\n{color:inherit;opacity:.72;font-size:15px;margin:0 0 26px}\n.zt-card\n{border:1px solid #e6e7ea;border-radius:16px;padding:22px;background:#fff;color:#16181d;margin-bottom:18px}\n.zt-form\n{display:flex;gap:10px;flex-wrap:wrap}\n.zt-form .zt-f\n{flex:1 1 190px}\n.zt-lab\n{display:block;font-size:12px;font-weight:600;color:#65686f;margin-bottom:6px;letter-spacing:.02em;text-transform:uppercase}\n.zt-in\n{width:100%;box-sizing:border-box;padding:12px 14px;border:1px solid #d3d5da !important;border-radius:10px;font-size:15px;background:#fff !important;color:#16181d !important}\n.zt-in::placeholder\n{color:#9aa0a8 !important;opacity:1;font-style:italic}\n.zt-in:focus\n{outline:none;border-color:#16181d;box-shadow:0 0 0 3px rgba(22,24,29,.08)}\n.zt-btn\n{background:#16181d !important;color:#fff !important;border:0;border-radius:10px;padding:13px 26px;font-size:15px;font-weight:600;cursor:pointer;align-self:flex-end}\n.zt-btn:hover\n{background:#33363d}\n.zt-hero\n{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;align-items:flex-start;margin-bottom:22px}\n.zt-status\n{font-size:24px;font-weight:700;margin:2px 0 4px;letter-spacing:-.01em}\n.zt-when\n{color:#65686f;font-size:14px;margin:0}\n.zt-ord\n{text-align:right}\n.zt-ord b\n{display:block;font-size:16px}\n.zt-ord span\n{color:#65686f;font-size:13px}\n.zt-bar\n{display:flex;margin:26px 0 10px}\n.zt-step\n{flex:1;text-align:center;position:relative}\n.zt-dot\n{width:15px;height:15px;border-radius:50%;background:#dfe1e5;margin:0 auto 9px;position:relative;z-index:2}\n.zt-step.on .zt-dot\n{background:#16181d}\n.zt-step.now .zt-dot\n{background:#16181d;box-shadow:0 0 0 5px rgba(22,24,29,.12)}\n.zt-step:before\n{content:\"\";position:absolute;top:7px;left:0;width:50%;height:2px;background:#dfe1e5;z-index:1}\n.zt-step:after\n{content:\"\";position:absolute;top:7px;right:0;width:50%;height:2px;background:#dfe1e5;z-index:1}\n.zt-step:first-child:before,.zt-step:last-child:after\n{display:none}\n.zt-step.on:before,.zt-step.on:after\n{background:#16181d}\n.zt-step.now:after\n{background:#dfe1e5}\n.zt-slab\n{font-size:11px;color:#8a8d94;font-weight:600;letter-spacing:.02em}\n.zt-step.on .zt-slab\n{color:#16181d}\n.zt-note\n{border-radius:12px;padding:14px 16px;font-size:14px;margin:18px 0 0;line-height:1.5;color:#16181d}\n.zt-warn\n{background:#fff6e6;border-left:3px solid #b98900}\n.zt-bad\n{background:#fdeeec;border-left:3px solid #c4262e}\n.zt-good\n{background:#eaf7ef;border-left:3px solid #0f7a3d}\n.zt-meta\n{display:flex;gap:26px;flex-wrap:wrap;margin-top:22px;padding-top:18px;border-top:1px solid #eeeff1}\n.zt-meta div p\n{margin:0}\n.zt-meta .k\n{font-size:11px;color:#8a8d94;text-transform:uppercase;letter-spacing:.04em;font-weight:600;margin-bottom:3px}\n.zt-meta .v\n{font-size:15px;font-weight:600}\n.zt-hist\n{list-style:none;margin:6px 0 0;padding:0}\n.zt-hist li\n{display:flex;gap:14px;padding:13px 0;border-bottom:1px solid #f2f3f5}\n.zt-hist li:last-child\n{border-bottom:0}\n.zt-hist .t\n{flex:0 0 118px;font-size:12px;color:#8a8d94;padding-top:2px}\n.zt-hist .d\n{font-size:14px}\n.zt-hist .l\n{font-size:12px;color:#8a8d94;margin-top:2px}\n.zt-help\n{text-align:center;color:inherit;opacity:.72;font-size:14px;margin-top:26px}\n.zt-help a\n{color:inherit;font-weight:600;text-decoration:underline}\n@media (max-width:600px)\n{\n.zt-h1{font-size:24px}\n.zt-ord{text-align:left}\n.zt-btn{width:100%}\n.zt-slab{font-size:10px}\n.zt-hist .t{flex:0 0 92px}\n}\n</style>\n`;\n\nfunction shell(inner: string) {\n  return `${CSS}<div class=\"zt-wrap\">${inner}</div>`;\n}\n\nfunction form(order = \"\", pin = \"\", err = \"\") {\n  return `\n  <h1 class=\"zt-h1\">Track your order</h1>\n  <p class=\"zt-sub\">Enter your order number and the last 4 digits of your phone number.</p>\n  ${err ? `<div class=\"zt-note zt-bad\">${esc(err)}</div>` : \"\"}\n  <div class=\"zt-card\">\n    <form method=\"get\" action=\"/apps/track\" class=\"zt-form\">\n      <div class=\"zt-f\">\n        <label class=\"zt-lab\" for=\"zt-o\">Order number</label>\n        <input class=\"zt-in\" id=\"zt-o\" name=\"order\" value=\"${esc(order)}\" placeholder=\"e.g. Z1001\" autocomplete=\"off\" required>\n      </div>\n      <div class=\"zt-f\">\n        <label class=\"zt-lab\" for=\"zt-p\">Phone - last 4 digits</label>\n        <input class=\"zt-in\" id=\"zt-p\" name=\"pin\" value=\"${esc(pin)}\" placeholder=\"e.g. 8695\" inputmode=\"numeric\" maxlength=\"4\" autocomplete=\"off\" required>\n      </div>\n      <button class=\"zt-btn\" type=\"submit\">Track</button>\n    </form>\n  </div>\n  <p class=\"zt-help\">Your order number is in your confirmation message. If something is not right, <a href=\"/pages/contact\">tell us</a>.</p>`;\n}\n\nexport const loader = async ({ request }: LoaderFunctionArgs) => {\n  // The signature is checked right here. If it is wrong, this throws a\n  // 401 by itself and nothing below ever runs.\n  await authenticate.public.appProxy(request);\n\n  const url = new URL(request.url);\n  const domain = shopFromProxy(url);\n  if (!domain) return liquid(shell(form(\"\", \"\", \"Something went wrong. Please open the page again.\")));\n\n  const shop = await db.shop.findUnique({ where: { domain } });\n  if (!shop) return liquid(shell(form()));\n\n  const num = (url.searchParams.get(\"n\") ?? \"\").trim();\n  const orderQ = (url.searchParams.get(\"order\") ?? \"\").trim();\n  const pin = (url.searchParams.get(\"pin\") ?? \"\").trim();\n\n  if (!num && !orderQ) return liquid(shell(form()));\n\n  /* ---------------- look it up ---------------- */\n  let rec: any = null;\n\n  if (num) {\n    const sh = await db.shipment.findFirst({\n      where: { trackingNo: num, order: { shopId: shop.id } },\n      orderBy: { createdAt: \"desc\" },\n      include: { order: { include: { shipments: { orderBy: { createdAt: \"desc\" } } } } },\n    });\n    rec = sh?.order ?? null;\n  } else {\n    // Z1005, z1005, #1005, 1005 - all of these should work.\n    const bare = orderQ.replace(/^[#Zz]+/, \"\");\n    const cands = await db.orderRecord.findMany({\n      where: {\n        shopId: shop.id,\n        OR: [\n          { orderNumber: orderQ },\n          { orderNumber: orderQ.toUpperCase() },\n          { orderNumber: `Z${bare}` },\n          { orderNumber: `#${bare}` },\n          { orderNumber: bare },\n        ],\n      },\n      include: { shipments: { orderBy: { createdAt: \"desc\" } } },\n      take: 5,\n    });\n\n    // A second proof. Without it, anyone could type Z1006 after Z1005\n    // and see someone else's address.\n    const four = pin.replace(/\\D/g, \"\").slice(-4);\n    rec = cands.find((c) => {\n      const ph = (c.phone ?? \"\").replace(/\\D/g, \"\");\n      return four.length === 4 && ph.endsWith(four);\n    }) ?? null;\n\n    if (!rec && cands.length > 0) {\n      return liquid(shell(form(orderQ, pin, \"Those last 4 digits do not match the phone number on this order.\")));\n    }\n  }\n\n  if (!rec) {\n    return liquid(\n      shell(form(orderQ, pin, \"Nothing matched that order number. Please check and try again.\")),\n    );\n  }\n\n  /* ---------------- show it ---------------- */\n  const ship = (rec.shipments ?? [])[0] ?? null;\n  const st = ship?.status ?? \"pending\";\n  const step = STEP_OF[st] ?? 0;\n  const label = ship ? STATUS_LABEL[st] ?? \"In progress\" : \"Order confirmed\";\n\n  const bar = STEPS.map((s, i) => {\n    const cls = i < step ? \"zt-step on\" : i === step ? \"zt-step on now\" : \"zt-step\";\n    return `<div class=\"${cls}\"><div class=\"zt-dot\"></div><div class=\"zt-slab\">${esc(s)}</div></div>`;\n  }).join(\"\");\n\n  let note = \"\";\n  if (st === \"delivered\") {\n    note = `<div class=\"zt-note zt-good\">This order has been delivered. If it has not reached you, tell us right away and we will look into it.</div>`;\n  } else if (st === \"exception\") {\n    note = `<div class=\"zt-note zt-warn\">The courier could not complete the delivery. They will try again. If the address or number needs to change, tell us now.</div>`;\n  } else if (st === \"returned\") {\n    note = `<div class=\"zt-note zt-bad\">The parcel is on its way back to us. We can send it out again if you want - just message us.</div>`;\n  } else if (st === \"out_for_delivery\") {\n    note = `<div class=\"zt-note zt-good\">It should reach you today. ${cashDue(rec) ? `Keep ${money(cashDue(rec), rec.currency)} ready.` : \"Payment is done, nothing to pay on delivery.\"}</div>`;\n  }\n\n  let scans: any[] = [];\n  try {\n    scans = ship?.scans ? JSON.parse(ship.scans) : [];\n  } catch {\n    scans = [];\n  }\n\n  const hist = scans.length\n    ? `<div class=\"zt-card\">\n        <p class=\"zt-lab\" style=\"margin-bottom:2px\">Journey</p>\n        <ul class=\"zt-hist\">${scans\n          .map(\n            (e: any) => `<li>\n              <div class=\"t\">${esc(fmt(e.time))}</div>\n              <div><div class=\"d\">${esc(e.desc || \"Update\")}</div>${\n                e.location ? `<div class=\"l\">${esc(e.location)}</div>` : \"\"\n              }</div>\n            </li>`,\n          )\n          .join(\"\")}</ul>\n      </div>`\n    : \"\";\n\n  const meta = [\n    ship?.carrier ? { k: \"Courier\", v: ship.carrier } : null,\n    ship?.trackingNo ? { k: \"Tracking number\", v: ship.trackingNo } : null,\n    cashDue(rec)\n      ? { k: \"Payment\", v: `Cash on delivery - ${money(cashDue(rec), rec.currency)}` }\n      : { k: \"Payment\", v: \"Prepaid\" },\n    rec.city ? { k: \"Delivering to\", v: rec.city } : null,\n  ]\n    .filter(Boolean)\n    .map((m: any) => `<div><p class=\"k\">${esc(m.k)}</p><p class=\"v\">${esc(m.v)}</p></div>`)\n    .join(\"\");\n\n  const body = `\n  <h1 class=\"zt-h1\">Your order</h1>\n  <p class=\"zt-sub\">This shows what the courier has scanned so far.</p>\n\n  <div class=\"zt-card\">\n    <div class=\"zt-hero\">\n      <div>\n        <p class=\"zt-lab\" style=\"margin-bottom:2px\">Status</p>\n        <p class=\"zt-status\">${esc(label)}</p>\n        <p class=\"zt-when\">${\n          ship?.lastEventAt\n            ? esc(`${ship.lastEventDesc || \"Updated\"} · ${fmt(ship.lastEventAt)}`)\n            : \"We are getting your parcel ready\"\n        }</p>\n      </div>\n      <div class=\"zt-ord\">\n        <b>${esc(rec.orderNumber)}</b>\n        <span>${esc(rec.itemLine || \"\")}</span>\n      </div>\n    </div>\n\n    <div class=\"zt-bar\">${bar}</div>\n    ${note}\n    ${meta ? `<div class=\"zt-meta\">${meta}</div>` : \"\"}\n  </div>\n\n  ${hist}\n\n  <p class=\"zt-help\">Something not right? <a href=\"/pages/contact\">Tell us</a> - we will speak to the courier ourselves.</p>\n  <p class=\"zt-help\" style=\"margin-top:10px\"><a href=\"/apps/track\">Track another order</a></p>`;\n\n  return liquid(shell(body));\n};\n"}, {"path": "prisma/schema.prisma", "fromShas": ["28622f558dd21130fadf98edafbea676b4ede059af20b9ba197e624a31adb926", "fa37d57cd8b7ab9ddbdf5710834ee78c42984cffc239461cc89113d904077407", "fec0106bb0f9ad33ac2ee17b65e7ad3aa5db1b27730ea85c30f1583764cf79b2"], "toSha": "28622f558dd21130fadf98edafbea676b4ede059af20b9ba197e624a31adb926", "content": "// This is your Prisma schema file,\r\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\r\n\r\ngenerator client {\r\n  provider = \"prisma-client-js\"\r\n}\r\n\r\n// Note that some adapters may set a maximum length for the String type by default, please ensure your strings are long\r\n// enough when changing adapters.\r\n// See https://www.prisma.io/docs/orm/reference/prisma-schema-reference#string for more information\r\ndatasource db {\n  provider  = \"postgresql\"\n  // The app runs through Neon's pooler: a web server opens and closes\n  // connections all day, and the pooler is what keeps the database from\n  // running out of them.\n  url       = env(\"DATABASE_URL\")\n  // Migrations cannot go through the pooler - they need advisory locks\n  // and DDL that PgBouncer does not pass through. So they take the\n  // direct endpoint instead.\n  directUrl = env(\"DIRECT_URL\")\n}\r\n\r\nmodel Session {\r\n  id            String    @id\r\n  shop          String\r\n  state         String\r\n  isOnline      Boolean   @default(false)\r\n  scope         String?\r\n  expires       DateTime?\r\n  accessToken   String\r\n  userId        BigInt?\r\n  firstName     String?\r\n  lastName      String?\r\n  email         String?\r\n  accountOwner  Boolean   @default(false)\r\n  locale        String?\r\n  collaborator  Boolean?  @default(false)\r\n  emailVerified Boolean?  @default(false)\r\n  refreshToken        String?\r\n  refreshTokenExpires DateTime?\r\n}\n\n// ============================================================================\n//  ZakTracking models\n//\n//  Paste this whole block at the very BOTTOM of prisma/schema.prisma.\n//  Leave the Session model and the datasource/generator above it alone.\n//\n//  Then run:   npx prisma migrate dev --name zaktracking\n// ============================================================================\n\n\n/// One row per merchant store. All settings and API keys live here.\nmodel Shop {\n  id          String   @id @default(cuid())\n  domain      String   @unique\n  installedAt DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // --- WhatsApp (Meta Cloud API) ---\n  waEnabled       Boolean @default(false)\n  waPhoneNumberId String?\n  waWabaId        String?\n  waToken         String?\n\n  // --- SMS (phase 2 - after DLT registration in India) ---\n  smsEnabled  Boolean @default(false)\n  smsApiKey   String?\n  smsSenderId String?\n\n  // --- courier tracking (17TRACK) ---\n  trackApiKey String?\n\n  // --- which messages are turned on ---\n  onOrderCreate    Boolean @default(true)\n  onOrderPaid      Boolean @default(true)\n  onFulfilled      Boolean @default(true)\n  /// Off by default. It fires once per order, on the first in-transit scan,\n  /// which on a short route lands moments after the shipped message.\n  onInTransit      Boolean @default(false)\n  onOutForDelivery Boolean @default(true)\n  onDelivered      Boolean @default(true)\n  onCancelled      Boolean @default(true)\n  onAbandoned      Boolean @default(false)\n  codConfirm       Boolean @default(true)\n\n  orders    OrderRecord[]\n  templates Template[]\n  messages  MessageLog[]\n  carts     AbandonedCart[]\n  inbound   InboundMessage[]\n\n  /// When the customer presses Cancel we do not cancel straight away - a\n  /// cancelled Shopify order can never be brought back. We wait, and if\n  /// they press Confirm in the meantime nothing happens at all.\n  autoCancel     Boolean @default(true)\n  /// Minutes to wait before a cancellation request is acted on.\n  cancelGraceMin Int     @default(30)\n\n  /// Discount code for the second abandoned-cart reminder.\n  /// If it is empty the second reminder is not sent at all - better than a fake code.\n  abandonCode String?\n}\n\n\n/// Our own copy of every order, so we never have to ask Shopify again.\nmodel OrderRecord {\n  id     String @id @default(cuid())\n  shopId String\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n\n  shopifyId   String\n  orderNumber String\n  customerName String?\n  phone        String?\n  email        String?\n  totalPrice   String?\n  currency     String?\n  financial    String?\n  gateway      String?\n\n  /// COD or prepaid. Needed as a guard on orders/paid - a COD order also\n  /// fires paid, but only when the courier deposits the cash.\n  isCod        Boolean   @default(false)\n  /// null = not asked yet, true = confirmed, false = declined\n  codConfirmed Boolean?\n  cancelledAt  DateTime?\n  /// Set when the customer presses Cancel on WhatsApp. Cleared the moment\n  /// they press Confirm instead. The cron acts on it once the grace period\n  /// set on the shop has passed.\n  cancelRequestedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  shipments Shipment[]\n  messages  MessageLog[]\n  inbound   InboundMessage[]\n\n  @@unique([shopId, shopifyId])\n  @@index([shopId, createdAt])\n\n  /// What is still to be collected on delivery. On a partial-payment COD\n  /// order this is less than the total, and it is the figure the customer\n  /// must be shown - never the total.\n  outstanding String?\n\n  /// \"Portable Blender + 1 more item\" - when a courier update arrives we do\n  /// not have Shopify's payload, so we keep it here.\n  itemLine String?\n  city    String?\n  address String?\n}\n\n\n/// One order can have several parcels. Each parcel gets its own row.\nmodel Shipment {\n  id      String      @id @default(cuid())\n  orderId String\n  order   OrderRecord @relation(fields: [orderId], references: [id], onDelete: Cascade)\n\n  fulfillmentId String\n  trackingNo    String?\n  carrier       String?\n  /// 17TRACK courier code\n  carrierCode   String?\n  trackUrl      String?\n\n  /// pending | info_received | in_transit | out_for_delivery\n  /// | delivered | exception | returned\n  status      String    @default(\"pending\")\n  lastEventAt DateTime?\n\n  /// whether it has been registered with the tracking API\n  registered Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([orderId, fulfillmentId])\n  @@index([trackingNo])\n\n  /// 17TRACK sub_status - e.g. \"DeliveryFailure_NoBody\"\n  subStatus     String?\n  lastEventDesc String?\n  lastEventLoc  String?\n  /// The whole journey as JSON - the tracking page is built from this\n  scans         String?\n  /// How many registration attempts have been made. We give up after 5.\n  regTries      Int     @default(0)\n}\n\n\n/// Every message we send. unique([orderId, event, channel]) is the one thing\n/// that stops the same customer getting \"your order has shipped\" twice.\nmodel MessageLog {\n  id     String @id @default(cuid())\n  shopId String\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n\n  orderId String?\n  order   OrderRecord? @relation(fields: [orderId], references: [id], onDelete: SetNull)\n\n  /// whatsapp | sms\n  channel String\n  /// order_created | cod_confirm | order_paid | shipped\n  /// | out_for_delivery | delivered | cancelled | abandoned_1 | abandoned_2\n  event String\n  to    String\n  body  String\n\n  /// queued | sent | failed\n  status     String  @default(\"queued\")\n  providerId String?\n  error      String?\n\n  sentAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@unique([orderId, event, channel])\n  @@index([shopId, createdAt])\n  @@index([status])\n}\n\n\n/// Where the merchant edits the text of their own messages.\nmodel Template {\n  id     String @id @default(cuid())\n  shopId String\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n\n  event   String\n  channel String\n  enabled Boolean @default(true)\n  body    String\n\n  updatedAt DateTime @updatedAt\n\n  @@unique([shopId, event, channel])\n}\n\n\n/// Abandoned cart. checkouts/update fires 10-15 times for one shopper, so we\n/// upsert on the token and keep pushing lastSeenAt forward.\n/// The moment an order arrives we fill convertedAt - then no reminder goes out.\nmodel AbandonedCart {\n  id     String @id @default(cuid())\n  shopId String\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n\n  token      String\n  phone      String?\n  name       String?\n  recoverUrl String?\n  total      String?\n  currency   String?\n  itemCount  Int     @default(0)\n\n  lastSeenAt  DateTime  @default(now())\n  reminder1At DateTime?\n  reminder2At DateTime?\n  convertedAt DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@unique([shopId, token])\n  @@index([shopId, lastSeenAt])\n}\n\n\n/// Shopify sends the same webhook two or three times (retries, network\n/// glitches). Each delivery carries a unique id - remembering it is the\n/// cheapest way to make every handler idempotent.\nmodel WebhookEvent {\n  id         String   @id\n  topic      String\n  shop       String\n  receivedAt DateTime @default(now())\n\n  @@index([shop, topic])\n}\n\n// ============================================================================\n//  Phase 2 - two changes\n//\n//  1. A WABA ID field on Shop (to read the template list)\n//  2. An OptOut table (to honour STOP)\n//\n//  The script adds both - nothing to do by hand.\n// ============================================================================\n\n/// Anyone who replies STOP lands here. Checked before every send.\n/// The promise in the footer is only true if we honour it.\nmodel OptOut {\n  id     String @id @default(cuid())\n  shopId String\n  phone  String\n\n  createdAt DateTime @default(now())\n\n  @@unique([shopId, phone])\n  @@index([shopId])\n}\n\n\n/// Every reply a customer sends. This is the merchant's inbox: a number on\n/// the WhatsApp Cloud API cannot be opened in the ordinary WhatsApp\n/// Business app, so what is stored here is the only record there is.\n///\n/// waMessageId is unique because Meta retries a webhook it thinks failed.\n/// Without it one \"Cancel\" could be acted on three times.\nmodel InboundMessage {\n  id     String @id @default(cuid())\n  shopId String\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n\n  orderId String?\n  order   OrderRecord? @relation(fields: [orderId], references: [id], onDelete: SetNull)\n\n  /// Meta's own message id\n  waMessageId String @unique\n  from        String\n  text        String\n  /// text | button | interactive | image | ...\n  kind        String\n  /// confirm | cancel | stop | start | none\n  intent      String @default(\"none\")\n\n  createdAt DateTime @default(now())\n\n  @@index([shopId, createdAt])\n}\n"}], "created": []};

const root = process.cwd();
const sha = (s) => createHash("sha256").update(s, "utf8").digest("hex");

if (!existsSync(join(root, "app", "routes")) || !existsSync(join(root, "prisma"))) {
  console.error("ERROR: this is not the project root (app/routes and prisma not found).");
  process.exit(1);
}

const problems = [];
const plan = [];

for (const f of PAYLOAD.modified) {
  const abs = join(root, f.path);
  if (!existsSync(abs)) { problems.push(`missing file: ${f.path}`); continue; }
  const current = sha(readFileSync(abs, "utf8"));
  if (current === f.toSha) { console.log(`skip    ${f.path} (already patched)`); continue; }
  if (!f.fromShas.includes(current)) {
    problems.push(`${f.path} is not a version this patch was built against (found ${current.slice(0, 16)})`);
    continue;
  }
  plan.push(f);
}

if (problems.length) {
  console.error("\nNothing was written. Fix these first:\n");
  for (const p of problems) console.error("  - " + p);
  process.exit(1);
}

if (plan.length === 0) { console.log("\nEverything is already applied. Nothing to do."); process.exit(0); }

for (const f of plan) {
  writeFileSync(join(root, f.path), f.content, "utf8");
  if (sha(readFileSync(join(root, f.path), "utf8")) !== f.toSha) {
    console.error(`ERROR: ${f.path} written but its checksum is wrong. Stopping.`);
    process.exit(1);
  }
  console.log(`ok      ${f.path}`);
}

console.log(`
Done - ${plan.length} file(s) written and checksum-verified.

Next:
  npx prisma migrate dev --name cod_outstanding
  git add .
  git commit -m "cod detection, real totals, tracking page fixes"
  git push
`);
